prereqs.script:
const fpCostText = "@FP Cost@";
let fpCost = parseInt(fpCostText);
if (isNaN(fpCost)) {
  `Invalid FP cost: ${fpCostText}`;
} else {
  "";
}

const msgtxt = []
if (self.level > 2) { msgtxt.push("Maximum Trait Level is 2!"); }
if (self.level > Math.max(0,entity.traitLevel('Psi Talent')) - 4) { msgtxt.push("You do NOT have Enough Psi Talent!"); } 
msgtxt.join("\n* ")

if (entity.exists) {
  const lspLevel = entity.traitLevel("Increased Long-Term Stability Points") - entity.traitLevel("Decreased Long-Term Stability Points");
  const lspLimit = ($iq + $will)/2;
  if (lspLevel < -lspLimit) {
    `Total negative LSP does not exceed ${lspLimit}, currently ${lspLevel}`
  } else {
    ""
  }
} else {
  ""
}

if (entity.exists) {
  var points = 0;
  for (const skill of entity.findSkills("@Skill@")) {
    points += skill.points;
  }
  if (points > 0) {
    "No points are invested in @Skill@"
  } else {
    ""
  }
} else {
  ""
}

var msgs = [];
var modifierCount = 0;
const hotMod = self.findActiveModifier("Hot");
const coldMod = self.findActiveModifier("Cold");
const degreesHotterMod = self.findActiveModifier("Degrees Hotter");
const degreesColderMod = self.findActiveModifier("Degrees Colder");
if (hotMod) {
  modifierCount++;
}
if (coldMod) {
  modifierCount++;
}
if (degreesHotterMod || degreesColderMod) {
  modifierCount++;
}
if (modifierCount > 1) {
  msgs.push("Hot, Cold, and Degrees Hotter/Colder must not be mixed")
}
if (entity.exists) {
  const expectedLevels = $ht * self.level;
  var foundLevels = 0;
  if (degreesHotterMod) {
    foundLevels += degreesHotterMod.level;
  }
  if (degreesColderMod) {
    foundLevels += degreesColderMod.level;
  }
  if (foundLevels != 0 && expectedLevels != foundLevels) {
    msgs.push(`Total levels of Degrees Hotter and Degrees Colder should be ${expectedLevels} not ${foundLevels}`)
  }
}
msgs.join("\n* ")

const msgtxt = []
if (self.children.some(child => child.findActiveModifier("Psionic") === null)) msgtxt.push("You have a Non-Psionic Trait");
msgtxt.join("\n* ")
